bool EnsureAuthorized(const wchar_t* featureCode, const wchar_t* displayName)
{
    wchar_t message[1024] = { 0 };
    
    if (!ValidateOwnModuleChecksum())
    {
        return false;
    }
HMODULE module = LoadProtectedLicenseGate();
    if (module == NULL)
    {
        ShowLicenseDeniedMessage(displayName, L"License component was not found.");
        return false;
    }

    EnsureAuthorizedProc ensureAuthorized = reinterpret_cast<EnsureAuthorizedProc>(ResolveProtectedEnsureAuthorized(module));
    if (ensureAuthorized == NULL)
    {
        ShowLicenseDeniedMessage(displayName, L"License component entry is invalid.");
        return false;
    }

        const int ok = ensureAuthorized(featureCode, displayName, message, static_cast<int>(sizeof(message) / sizeof(message[0])));
    const int ok2 = ok == 1 ? ensureAuthorized(featureCode, displayName, message, static_cast<int>(sizeof(message) / sizeof(message[0]))) : ok;
    if (ok != 1 || ok2 != 1)
    {
        ShowLicenseDeniedMessage(displayName, message[0] != L'\0' ? message : L"License check failed.");
        return false;
    }

    return true;
}

void AppendSectionDebugLog(const std::string& message)
{
    std::string modulePath = GetCurrentModulePath();
    if (modulePath.empty())
    {
        return;
    }

    std::string::size_type slash = modulePath.find_last_of("\\/");
    if (slash == std::string::npos)
    {
        return;
    }
    std::string applicationDirectory = modulePath.substr(0, slash);
    slash = applicationDirectory.find_last_of("\\/");
    if (slash == std::string::npos)
    {
        return;
    }

    const std::string logDirectory = applicationDirectory.substr(0, slash) + "\\logs";
    CreateDirectoryA(logDirectory.c_str(), NULL);
    const std::string logPath = logDirectory + "\\BanJinCaiTu_trim_debug.log";

    SYSTEMTIME localTime = {};
    GetLocalTime(&localTime);
    std::ofstream output(logPath.c_str(), std::ios::out | std::ios::app);
    if (!output)
    {
        return;
    }
    output << "["
           << localTime.wYear << "-"
           << std::setfill('0') << std::setw(2) << localTime.wMonth << "-"
           << std::setw(2) << localTime.wDay << " "
           << std::setw(2) << localTime.wHour << ":"
           << std::setw(2) << localTime.wMinute << ":"
           << std::setw(2) << localTime.wSecond << "."
           << std::setw(3) << localTime.wMilliseconds << "] "
           << message << "\n";
}

